<?php
require_once __DIR__.'/../includes/database.php';require_once __DIR__.'/../includes/team-inventory.php';require_once __DIR__.'/../includes/pallet-activity.php';require_once __DIR__.'/../includes/stock-transfer.php';
function inner_check(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
function inner_invalid(array $input):void{try{stock_product_input($input);}catch(CatalogException $e){inner_check($e->status===422,'invalid data status');return;}throw new RuntimeException('Invalid composition accepted');}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);initialize_database($db);initialize_database($db);
foreach(['Owner','Admin','Operator','Other']as$i=>$name)stock_query($db,'INSERT INTO users(name,public_name,email,password_hash) VALUES(?,?,?,?)',[$name,$name,'inner'.$i.'@example.invalid','unused']);
$base=['ean'=>'96385074','name'=>'Caja con paquetes','amount'=>2,'kind'=>'boxes','pack_size'=>180,'inner_pack_size'=>30,'expires'=>'2030-01-01'];
inner_check(stock_product_input($base)['units']===360,'two boxes times six packages times thirty units');
foreach([['inner_pack_size'=>[]],['inner_pack_size'=>-1],['inner_pack_size'=>181],['inner_pack_size'=>31],['inner_pack_size'=>'1.5'],['kind'=>'units'],['kind'=>'packs'],['pack_size'=>1000001]]as$bad)inner_invalid([...$base,...$bad]);
inner_check(stock_product_input([...$base,'inner_pack_size'=>0,'pack_size'=>12])['units']===24,'plain boxes unchanged');
$label=stock_generate($db,1);$p=stock_claim($db,$label['code'],1);stock_save_product($db,1,[...$base,'pallet_id'=>$p['id']]);$read=fn()=>stock_detail($db,$p['code'],1)['products'][0];$v=$read();inner_check($v['units']==360&&$v['pack_size']==180&&$v['inner_pack_size']==30,'composition survives detail round trip');
$reference=stock_query($db,'SELECT * FROM stock_product_references WHERE ean=? AND kind=?',[$base['ean'],'boxes'])->fetch();inner_check((int)$reference['inner_pack_size']===30&&(int)$reference['pack_size']===180,'reference retains both factors');
stock_save_product($db,1,[...$base,'pallet_id'=>$p['id'],'product_id'=>$v['id'],'revision'=>$v['revision'],'amount'=>3]);$v=$read();inner_check($v['units']==540&&$v['inner_pack_size']==30,'edit does not flatten composition');
stock_save_product($db,1,[...$base,'pallet_id'=>$p['id'],'amount'=>1]);$v=$read();inner_check($v['units']==720&&$v['kind']==='boxes'&&$v['inner_pack_size']==30,'identical nested loads merge retaining composition');
stock_deduct_product($db,1,['pallet_id'=>$p['id'],'product_id'=>$v['id'],'revision'=>$v['revision'],'amount'=>1,'kind'=>'packs','pack_size'=>30]);$v=$read();inner_check($v['units']==690&&$v['inner_pack_size']==30&&$v['pack_size']==180,'inner withdrawal removes thirty and retains composition');
stock_deduct_product($db,1,['pallet_id'=>$p['id'],'product_id'=>$v['id'],'revision'=>$v['revision'],'amount'=>1,'kind'=>'units']);$v=$read();inner_check($v['units']==689&&$v['inner_pack_size']==30,'loose unit withdrawal remains exact');
try{stock_save_product($db,4,[...$base,'pallet_id'=>$p['id']]);throw new RuntimeException('foreign edit accepted');}catch(CatalogException $e){inner_check($e->status===403,'permissions unchanged');}
stock_query($db,"INSERT INTO stock_branches(owner_id,name,address,locality,province) VALUES(2,'Prueba','A','B','C')");stock_query($db,"INSERT INTO branch_workspaces(owner_id,name) VALUES(2,'Equipo')");stock_query($db,'INSERT INTO branch_workspace_locations(branch_id,workspace_id) VALUES(1,1)');stock_query($db,"INSERT INTO branch_team_members(branch_id,user_id,role) VALUES(1,3,'operator')");team_select($db,3,1);
$scan=team_scan($db,3,$p['code'],1);$r=$scan['pallet']['team_request'];$draft=$scan['pallet']['products'][0];inner_check($draft['inner_pack_size']==30,'proposal copies composition');
team_request_edit($db,3,1,[...$base,'action'=>'save_product','pallet_id'=>$p['id'],'product_id'=>$draft['id'],'revision'=>$draft['revision'],'amount'=>2,'inner_pack_size'=>60]);$projected=team_inventory_page($db,2,1,'lotes',['ean'=>$base['ean'],'expires'=>$base['expires']])['items'][0];inner_check($projected['inner_pack_size']==60&&$projected['original_inner_pack_size']==30,'team projection preserves original and proposed composition');inner_check($read()['units']==689,'pending edit never changes owner stock');
$r=team_pallet_request($db,$p['id'],1);team_request_resolve($db,1,$r['id'],'accepted',$r['revision']);$v=$read();inner_check($v['units']==360&&$v['inner_pack_size']==60,'approval applies changed factor, not only quantity');
$label=stock_generate($db,1);$target=stock_claim($db,$label['code'],1);stock_save_product($db,1,[...$base,'pallet_id'=>$target['id']]);$preview=stock_transfer_preview($db,1,['pallet_id'=>$p['id'],'mode'=>'pallet','target_code'=>$target['code']]);
// Mixed packaging must not invent a single composition after a merge.
$transfer=array_map('strval',['pallet_id'=>$p['id'],'mode'=>'pallet','target_code'=>$target['code'],...$preview]);stock_transfer_commit($db,1,$transfer);$merged=stock_detail($db,$target['code'],1)['products'][0];inner_check($merged['units']==720&&$merged['inner_pack_size']==0&&$merged['kind']==='units','mixed compositions merge as exact units');
echo "OK: nested composition validation, old boxes, save/edit/reference/merge, exact inner and loose withdrawals, permissions, team proposal/projection/approval and mixed transfer.\n";
